const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Lake Menindee location
  const lakeMenindee = ee.Geometry.Point([142.4, -32.4]);
  const region = lakeMenindee.buffer(15000); // 15km buffer to cover lake area

  // 2. Date definitions
  const date1 = '2017-01-27';
  const date2 = '2019-02-02';
  const dateRange = 15; // days before/after to find images

  // 3. Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 4. Get Sentinel-2 images for both dates
  const col1 = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(region)
    .filterDate(ee.Date(date1).advance(-dateRange, 'day'), 
                ee.Date(date1).advance(dateRange, 'day'))
    .map(maskS2clouds);

  const col2 = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(region)
    .filterDate(ee.Date(date2).advance(-dateRange, 'day'), 
                ee.Date(date2).advance(dateRange, 'day'))
    .map(maskS2clouds);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`2017 Images: ${size1}, 2019 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("Trying Landsat 8 fallback...");

    function maskL8clouds(image) {
      const qa = image.select('QA_PIXEL');
      const cloudMask = qa.bitwiseAnd(1 << 3).eq(0)
          .and(qa.bitwiseAnd(1 << 4).eq(0));
      return image.updateMask(cloudMask);
    }

    const l8col1 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(region)
      .filterDate(ee.Date(date1).advance(-dateRange, 'day'), 
                  ee.Date(date1).advance(dateRange, 'day'))
      .map(maskL8clouds);

    const l8col2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(region)
      .filterDate(ee.Date(date2).advance(-dateRange, 'day'), 
                  ee.Date(date2).advance(dateRange, 'day'))
      .map(maskL8clouds);

    const l8size1 = await l8col1.size().getInfo();
    const l8size2 = await l8col2.size().getInfo();

    console.log(`Landsat 2017: ${l8size1}, Landsat 2019: ${l8size2}`);

    if (l8size1 === 0 || l8size2 === 0) {
      console.log("<answer>C1</answer>");
      return;
    }

    // Use Landsat data
    const img1 = l8col1.median();
    const img2 = l8col2.median();

    const ndwi1 = img1.normalizedDifference(['SR_B3', 'SR_B5']);
    const ndwi2 = img2.normalizedDifference(['SR_B3', 'SR_B5']);

    const water1 = ndwi1.gt(0);
    const water2 = ndwi2.gt(0);

    const stats1 = await water1.reduceRegion({
      reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
      geometry: region,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    const stats2 = await water2.reduceRegion({
      reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
      geometry: region,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    const waterPixels1 = stats1.nd_sum || 0;
    const waterPixels2 = stats2.nd_sum || 0;
    const validPixels1 = stats1.nd_count || 0;
    const validPixels2 = stats2.nd_count || 0;

    console.log(`2017: Water=${waterPixels1}, Valid=${validPixels1}`);
    console.log(`2019: Water=${waterPixels2}, Valid=${validPixels2}`);

    if (validPixels1 === 0 || validPixels2 === 0) {
      console.log("<answer>C2</answer>");
      return;
    }

    if (waterPixels2 < waterPixels1) {
      console.log("<answer>A</answer>");
    } else {
      console.log("<answer>B</answer>");
    }
    return;
  }

  // 5. Process Sentinel-2 data
  const img1 = col1.median();
  const img2 = col2.median();

  // 6. Calculate NDWI (water index)
  const ndwi1 = img1.normalizedDifference(['B3', 'B8']);
  const ndwi2 = img2.normalizedDifference(['B3', 'B8']);

  // 7. Threshold to identify water (NDWI > 0)
  const water1 = ndwi1.gt(0);
  const water2 = ndwi2.gt(0);

  // 8. Count water pixels
  const stats1 = await water1.reduceRegion({
    reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = await water2.reduceRegion({
    reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const waterPixels1 = stats1.nd_sum || 0;
  const waterPixels2 = stats2.nd_sum || 0;
  const validPixels1 = stats1.nd_count || 0;
  const validPixels2 = stats2.nd_count || 0;

  console.log(`2017: Water=${waterPixels1}, Valid=${validPixels1}`);
  console.log(`2019: Water=${waterPixels2}, Valid=${validPixels2}`);

  // 9. Validation
  if (validPixels1 === 0 || validPixels2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (waterPixels1 === null || waterPixels2 === null) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 10. Compare water extent
  if (waterPixels2 < waterPixels1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
